const wines=[{id:1,name:'Cabernet Sauvignon',type:'Vang đỏ',origin:'PHÁP',note:'Đậm đà, hương lý chua đen và gỗ sồi.',price:650000,color:'#681b32'},{id:2,name:'Chardonnay',type:'Vang trắng',origin:'ÚC',note:'Mềm mại, hương táo vàng và vani nhẹ.',price:490000,color:'#d1b363'},{id:3,name:'Rosé de Provence',type:'Vang hồng',origin:'PHÁP',note:'Thanh mát, hương dâu tây và hoa trắng.',price:580000,color:'#d9908f'},{id:4,name:'Merlot',type:'Vang đỏ',origin:'CHILE',note:'Êm dịu, hương mận chín và anh đào.',price:420000,color:'#681b32'},{id:5,name:'Sauvignon Blanc',type:'Vang trắng',origin:'NEW ZEALAND',note:'Tươi sáng, hương cam quýt và trái cây nhiệt đới.',price:560000,color:'#d1b363'},{id:6,name:'Pinot Noir',type:'Vang đỏ',origin:'Ý',note:'Tinh tế, hương quả mọng và gia vị nhẹ.',price:720000,color:'#681b32'}];
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(n);const cart=new Map();const dialog=document.querySelector('#cart');let toastTimer;
document.querySelector('#products').innerHTML=wines.map(w=>`<article class="product"><div class="product-top"><span class="type"><i class="swatch" style="--swatch:${w.color}" aria-hidden="true"></i>${w.type}</span><span class="number">0${w.id}</span></div><p class="origin">${w.origin} · 750 ML</p><h3>${w.name}</h3><p class="tasting">${w.note}</p><div class="product-bottom"><span class="price">${money(w.price)}</span><button class="add" data-add="${w.id}" aria-label="Thêm ${w.name} vào giỏ">Thêm +</button></div></article>`).join('');
function renderCart(){let total=0,count=0;document.querySelector('#cart-items').innerHTML=[...cart].map(([id,qty])=>{const w=wines.find(w=>w.id===id);total+=w.price*qty;count+=qty;return `<div class="cart-item"><div><strong>${w.name}</strong><small>${money(w.price)}</small></div><div class="quantity"><button data-change="${id}" data-delta="-1" aria-label="Giảm ${w.name}">−</button><span>${qty}</span><button data-change="${id}" data-delta="1" aria-label="Tăng ${w.name}">+</button></div></div>`}).join('')||'<p>Giỏ hàng đang trống. Chọn một chai vang bạn yêu thích.</p>';document.querySelector('#count').textContent=count;document.querySelector('#total').textContent=money(total);document.querySelector('#export').disabled=!count;}
document.querySelector('#products').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(!b)return;const id=Number(b.dataset.add);cart.set(id,(cart.get(id)||0)+1);renderCart();const toast=document.querySelector('#toast');toast.textContent=`Đã thêm ${wines.find(w=>w.id===id).name} vào giỏ`;toast.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.style.display='none',2500)});
document.querySelector('#cart-items').addEventListener('click',e=>{const b=e.target.closest('[data-change]');if(!b)return;const id=Number(b.dataset.change),qty=(cart.get(id)||0)+Number(b.dataset.delta);if(qty<=0)cart.delete(id);else cart.set(id,qty);renderCart()});
document.querySelector('#open-cart').onclick=()=>{renderCart();dialog.showModal()};document.querySelector('#close-cart').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#export').onclick=()=>{let total=0;const lines=[...cart].map(([id,qty])=>{const w=wines.find(w=>w.id===id);total+=w.price*qty;return `${w.name} × ${qty}: ${money(w.price*qty)}`});const blob=new Blob(['\uFEFFVANG — DANH SÁCH ĐÃ CHỌN\n\n'+lines.join('\n')+'\n\nTổng cộng: '+money(total)+'\n\nBản mẫu. Chưa gửi đơn hàng hoặc thanh toán.'],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='vang-danh-sach.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};renderCart();
